import re

def _get_children_of_kind(doc, scope, title_suffix, kind_filter=None):
    children = scope_nodes(doc, scope)
    results = []
    for node in children:
        if node["title"].endswith(title_suffix):
            if kind_filter is None or node.get("kind") == kind_filter:
                results.append(node)
    return results

def entities(doc, scope) -> list:
    obj_nodes = _get_children_of_kind(doc, scope, ": Objects", "list")
    result = []
    for obj_node in obj_nodes:
        if "lines" not in obj_node:
            continue
        for line in obj_node["lines"]:
            m = re.match(r"Object (\d+):\s*(.+?)\s*\(color=(\w+), material=(\w+), shape=(\w+)\)", line)
            if m:
                result.append({"id": m.group(1), "description": m.group(2)})
    return result

def recorded_end(doc, scope) -> float:
    max_frame = -1
    children = scope_nodes(doc, scope)
    for node in children:
        if node["title"].endswith(": Motion log") and "table" in node:
            rows = table_rows(node)
            for idx, row in rows:
                f = int(row["frame"])
                if f > max_frame:
                    max_frame = f
        if node["title"].endswith(": Events") and "lines" in node:
            for line in node["lines"]:
                m = re.match(r"Frame (\d+)", line)
                if m:
                    f = int(m.group(1))
                    if f > max_frame:
                        max_frame = f
    return float(max_frame) if max_frame >= 0 else 127.0

def _parse_obj_info(doc, scope):
    obj_info = {}
    obj_nodes = _get_children_of_kind(doc, scope, ": Objects", "list")
    for obj_node in obj_nodes:
        if "lines" not in obj_node:
            continue
        for line in obj_node["lines"]:
            m = re.match(r"Object (\d+):\s*(.+?)\s*\(color=(\w+), material=(\w+), shape=(\w+)\)", line)
            if m:
                obj_info[m.group(1)] = {"color": m.group(3), "material": m.group(4), "shape": m.group(5)}
    return obj_info

def _parse_first_motion(doc, scope):
    first_motion = {}
    motion_nodes = _get_children_of_kind(doc, scope, ": Motion log", "table")
    for motion_node in motion_nodes:
        if "table" not in motion_node:
            continue
        rows = table_rows(motion_node)
        for idx, row in rows:
            obj_match = re.match(r"(\d+)\s+", row["object"])
            if obj_match:
                oid = obj_match.group(1)
                if oid not in first_motion:
                    first_motion[oid] = {
                        "frame": int(row["frame"]),
                        "x": float(row["x"]), "y": float(row["y"]),
                        "vx": float(row["vx"]), "vy": float(row["vy"]),
                        "speed": float(row["speed"]),
                        "node_id": motion_node["node_id"],
                        "row_idx": idx
                    }
    return first_motion

def inputs(doc, scope) -> list:
    children = scope_nodes(doc, scope)
    obj_info = _parse_obj_info(doc, scope)
    first_motion = _parse_first_motion(doc, scope)
    events_node = None
