        if node["title"].endswith(": Events"):
            events_node = node
            break
    result = []
    if not events_node or "lines" not in events_node:
        return result
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r"Frame (\d+):\s*(.+)", line)
        if not m:
            continue
        frame = int(m.group(1))
        rest = m.group(2)
        present_m = re.match(r"Object (\d+) \((.+?)\) is in view when the video begins\.", rest)
        if present_m:
            oid = present_m.group(1)
            fields = dict(obj_info.get(oid, {}))
            src = [[events_node["node_id"], line_idx]]
            if oid in first_motion:
                fm = first_motion[oid]
                fields["x"] = fm["x"]
                fields["y"] = fm["y"]
                fields["vx"] = fm["vx"]
                fields["vy"] = fm["vy"]
                fields["speed"] = fm["speed"]
                src.append([fm["node_id"], fm["row_idx"], ["frame", "object", "x", "y", "vx", "vy", "speed"]])
            result.append({"id": f"present-{oid}", "time": float(frame), "kind": "present_at_start",
                           "entities": [oid], "fields": fields, "src": src})
            continue
        enter_m = re.match(r"Object (\d+) \((.+?)\) enters the scene\.", rest)
        if enter_m:
            oid = enter_m.group(1)
            fields = dict(obj_info.get(oid, {}))
            result.append({"id": f"enter-{oid}", "time": float(frame), "kind": "enter",
                           "entities": [oid], "fields": fields, "src": [[events_node["node_id"], line_idx]]})
    return result

def outcomes(doc, scope) -> list:
