import math
import re

def _read_motion_log(doc, scope):
    """Read motion log from document for state initialization."""
    if isinstance(scope, dict):
        scope = scope.get("title", scope)
    motion_data = {}
    children = scope_nodes(doc, scope)
    for node in children:
        if node["title"].endswith(": Motion log") and "table" in node:
            rows = table_rows(node)
            for idx, row in rows:
                if not row.get("frame") or row["frame"] == "":
                    continue
                try:
                    f = int(row["frame"])
                except (ValueError, TypeError):
                    continue
                m = re.match(r"(\d+)\s+", row.get("object", ""))
                if m:
                    oid = m.group(1)
                    try:
                        motion_data[(f, oid)] = {
                            "x": float(row["x"]), "y": float(row["y"]),
                            "vx": float(row["vx"]), "vy": float(row["vy"]),
                            "speed": float(row["speed"]),
                        }
                    except (ValueError, TypeError):
                        continue
    return motion_data

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_threshold", 0.1)

    if horizon is None:
        h = recorded_end(doc, scope)
        horizon = h if h is not None else 127.0
    if start is None:
        start = 0.0

    DT = 0.0275
    FRICTION = {"metal": 0.993, "rubber": 0.990}
    RADIUS = {"sphere": 0.21, "cube": 0.27, "cylinder": 0.20}
    MASS = {
        ("metal", "sphere"): 1.0, ("metal", "cube"): 2.0, ("metal", "cylinder"): 1.5,
        ("rubber", "sphere"): 0.5, ("rubber", "cube"): 1.0, ("rubber", "cylinder"): 0.75,
    }
    E = 0.3
    BOUNDARY = 5.0
    COLLISION_THRESHOLD = 0.52

    motion_log = _read_motion_log(doc, scope)

    objects = {}
    entry_times = {}

    for inp in inputs:
        if inp["time"] > horizon:
            continue
        oid = inp["entities"][0]
        fields = inp["fields"]
        mat = fields.get("material", "rubber")
        shape = fields.get("shape", "sphere")

        if inp["kind"] == "present_at_start":
            objects[oid] = {
                "x": float(fields.get("x", 0)), "y": float(fields.get("y", 0)),
                "vx": float(fields.get("vx", 0)), "vy": float(fields.get("vy", 0)),
                "material": mat, "shape": shape, "active": True,
            }
        elif inp["kind"] == "enter":
            entry_times[oid] = int(inp["time"])
            entry_state = motion_log.get((entry_times[oid], oid))
            if entry_state:
                objects[oid] = {
                    "x": entry_state["x"], "y": entry_state["y"],
                    "vx": entry_state["vx"], "vy": entry_state["vy"],
                    "material": mat, "shape": shape, "active": False,
                    "entry_time": entry_times[oid],
                }
            else:
                best_state = None
                best_df = float('inf')
                for (f, o), state in motion_log.items():
                    if o == oid:
                        df = abs(f - entry_times[oid])
                        if df < best_df:
                            best_df = df
                            best_state = dict(state)
                if best_state is not None:
                    objects[oid] = {
                        "x": best_state["x"], "y": best_state["y"],
                        "vx": best_state["vx"], "vy": best_state["vy"],
                        "material": mat, "shape": shape, "active": False,
                        "entry_time": entry_times[oid],
                    }
                else:
                    objects[oid] = {
                        "x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0,
                        "material": mat, "shape": shape, "active": False,
                        "entry_time": entry_times[oid],
                    }

    start_frame = max(0, int(math.floor(start)))
    end_frame = int(horizon)

    for oid in objects:
        best_state = None
        best_f = -1
        for (f, o), state in motion_log.items():
            if o == oid and f <= start_frame:
                if f > best_f:
                    best_f = f
                    best_state = dict(state)

        if best_state is not None:
            frames_to_sim = start_frame - best_f
            vx, vy = best_state["vx"], best_state["vy"]
            x, y = best_state["x"], best_state["y"]
            mat = objects[oid]["material"]
            fric = FRICTION.get(mat, 0.992)

            for _ in range(frames_to_sim):
                speed = math.hypot(vx, vy)
                if speed < stationary_threshold:
                    vx, vy = 0.0, 0.0
                    break
                vx *= fric
                vy *= fric
                x += vx * DT
                y += vy * DT

            objects[oid]["x"] = x
            objects[oid]["y"] = y
            objects[oid]["vx"] = vx
            objects[oid]["vy"] = vy
            objects[oid]["active"] = True

    outcomes = []
    collided_pairs = set()
    exited_oids = set()

    for frame in range(start_frame, end_frame + 1):
        for oid, et in entry_times.items():
            if et == frame and oid in objects:
                objects[oid]["active"] = True

        active_oids = sorted([oid for oid, obj in objects.items()
                             if obj["active"] and oid not in exited_oids])

        for i in range(len(active_oids)):
            for j in range(i + 1, len(active_oids)):
                o1, o2 = active_oids[i], active_oids[j]
                pair = (o1, o2)
                if pair in collided_pairs:
                    continue

                obj1, obj2 = objects[o1], objects[o2]
                dx = obj2["x"] - obj1["x"]
                dy = obj2["y"] - obj1["y"]
                dist = math.hypot(dx, dy)

                if dist < 0.001:
                    continue

                if dist < COLLISION_THRESHOLD:
                    collided_pairs.add(pair)
                    nx, ny = dx / dist, dy / dist
                    v1n = obj1["vx"] * nx + obj1["vy"] * ny
                    v2n = obj2["vx"] * nx + obj2["vy"] * ny

                    if v1n > v2n:
                        m1 = MASS.get((obj1["material"], obj1["shape"]), 1.0)
                        m2 = MASS.get((obj2["material"], obj2["shape"]), 1.0)

                        v_rel = v1n - v2n
                        j_imp = -(1 + E) * v_rel * m1 * m2 / (m1 + m2)

                        obj1["vx"] += j_imp / m1 * nx
                        obj1["vy"] += j_imp / m1 * ny
                        obj2["vx"] -= j_imp / m2 * nx
                        obj2["vy"] -= j_imp / m2 * ny

                        outcomes.append({
                            "time": float(frame),
                            "kind": "collide",
                            "entities": [o1, o2],
                            "value": None,
                            "src": [],
                        })

        for oid in list(objects.keys()):
            obj = objects[oid]
            if not obj["active"] or oid in exited_oids:
                continue
            if abs(obj["x"]) > BOUNDARY or abs(obj["y"]) > BOUNDARY:
                exited_oids.add(oid)
                obj["active"] = False
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": [],
                })

        for oid, obj in objects.items():
            if not obj["active"] or oid in exited_oids:
                continue
            speed = math.hypot(obj["vx"], obj["vy"])
            if speed < stationary_threshold:
                obj["vx"] = 0.0
                obj["vy"] = 0.0
                continue
            fric = FRICTION.get(obj["material"], 0.992)
            obj["vx"] *= fric
            obj["vy"] *= fric
            obj["x"] += obj["vx"] * DT
            obj["y"] += obj["vy"] * DT

    return outcomes

