    motion_node = None
    for c in children:
        if c["title"].endswith(": Motion log") and "table" in c:
            motion_node = c
            break
    if not motion_node:
        return {}
    rows = table_rows(motion_node)
    data = {} # (frame, obj_id) -> {x, y, vx, vy, speed}
    for idx, row in rows:
        f = int(row["frame"])
        obj_match = re.match(r"(\d+)\s+", row["object"])
        if obj_match:
            oid = obj_match.group(1)
            data[(f, oid)] = {"x": float(row["x"]), "y": float(row["y"]), 
