    if not events_node:
        return []
    events = []
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r"Frame (\d+):\s*(.+)", line)
        if m:
            frame = int(m.group(1))
            rest = m.group(2)
            collide_m = re.match(r"Object (\d+) \((.+?)\) collides with Object (\d+) \((.+?)\)\.", rest)
            if collide_m:
                events.append({"time": frame, "kind": "collide", "entities": [collide_m.group(1), collide_m.group(3)]})
