                vy *= fric
                x += vx * DT
                y += vy * DT

            objects[oid]["x"] = x
            objects[oid]["y"] = y
            objects[oid]["vx"] = vx
            objects[oid]["vy"] = vy
            objects[oid]["active"] = True

    outcomes = []
    collided_pairs = set()
    exited_oids = set()

    for frame in range(start_frame, end_frame + 1):
        for oid, et in entry_times.items():
            if et == frame and oid in objects:
                objects[oid]["active"] = True

        active_oids = sorted([oid for oid, obj in objects.items()
                             if obj["active"] and oid not in exited_oids])

        for i in range(len(active_oids)):
            for j in range(i + 1, len(active_oids)):
                o1, o2 = active_oids[i], active_oids[j]
                pair = (o1, o2)
                if pair in collided_pairs:
                    continue

                obj1, obj2 = objects[o1], objects[o2]
                dx = obj2["x"] - obj1["x"]
                dy = obj2["y"] - obj1["y"]
                dist = math.hypot(dx, dy)

                if dist < 0.001:
                    continue

                if dist < COLLISION_THRESHOLD:
                    collided_pairs.add(pair)
                    nx, ny = dx / dist, dy / dist
                    v1n = obj1["vx"] * nx + obj1["vy"] * ny
                    v2n = obj2["vx"] * nx + obj2["vy"] * ny

                    if v1n > v2n:
                        m1 = MASS.get((obj1["material"], obj1["shape"]), 1.0)
                        m2 = MASS.get((obj2["material"], obj2["shape"]), 1.0)

                        v_rel = v1n - v2n
                        j_imp = -(1 + E) * v_rel * m1 * m2 / (m1 + m2)

                        obj1["vx"] += j_imp / m1 * nx
                        obj1["vy"] += j_imp / m1 * ny
                        obj2["vx"] -= j_imp / m2 * nx
                        obj2["vy"] -= j_imp / m2 * ny

                        outcomes.append({
                            "time": float(frame),
                            "kind": "collide",
                            "entities": [o1, o2],
                            "value": None,
                            "src": [],
                        })

        for oid in list(objects.keys()):
            obj = objects[oid]
            if not obj["active"] or oid in exited_oids:
                continue
            if abs(obj["x"]) > BOUNDARY or abs(obj["y"]) > BOUNDARY:
                exited_oids.add(oid)
                obj["active"] = False
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": [],
                })

        for oid, obj in objects.items():
            if not obj["active"] or oid in exited_oids:
                continue
            speed = math.hypot(obj["vx"], obj["vy"])
            if speed < stationary_threshold:
                obj["vx"] = 0.0
                obj["vy"] = 0.0
                continue
            fric = FRICTION.get(obj["material"], 0.992)
            obj["vx"] *= fric
            obj["vy"] *= fric
            obj["x"] += obj["vx"] * DT
            obj["y"] += obj["vy"] * DT

    return outcomes
